SLUG_TR={'rhinoplasty':'burun-estetigi','revision-rhinoplasty':'burun-revizyonu','breast-augmentation':'meme-buyutme','breast-reduction':'meme-kucultme','abdominoplasty':'karin-germe','blepharoplasty':'goz-kapagi-estetigi','gynecomastia':'jinekomasti','liposuction':'liposuction'}
SLUG_EN={'rhinoplasty':'rhinoplasty','revision-rhinoplasty':'secondary-rhinoplasty','breast-augmentation':'breast-augmentation','breast-reduction':'breast-reduction','abdominoplasty':'abdominoplasty','blepharoplasty':'eyelid-surgery','gynecomastia':'gynecomastia-surgery','liposuction':'body-aesthetic'}
ROUTES_TR={'about':'hakkimizda','procedures':'uzmanlik-alanlari','research':'bilimsel-yayinlar','patients':'yurt-disi-hastalar','contact':'iletisim','privacy':'gizlilik'}
def path(lang,kind='home',slug=None):
    prefix='' if lang=='tr' else '/'+lang
    if kind=='home': return (prefix or '')+'/'
    if kind=='proc':
        if lang=='tr': return '/'+SLUG_TR[slug]+'/'
        if lang=='en': return '/en/'+SLUG_EN[slug]+'/'
        return f'{prefix}/procedures/{slug}/'
    return f'{prefix}/{ROUTES_TR.get(kind,kind) if lang=="tr" else kind}/'

def esc(x):return html.escape(str(x),quote=True)
def link(lang,kind='home',slug=None):return path(lang,kind,slug)
def breadcrumbs(lang,kind,slug=None):
    t=T[lang]; title=t['nav'][{'about':1,'procedures':2,'research':3,'patients':4,'contact':5}.get(kind,0)] if kind!='proc' else P[slug][lang][0]
    return f'<nav class="crumb wrap" aria-label="Breadcrumb"><a href="{link(lang)}">{esc(t["nav"][0])}</a><span aria-hidden="true">/</span><span>{esc(title)}</span></nav>'
def hrelang(kind,slug=None):
    entries=[f'<link rel="alternate" hreflang="{lang}" href="{DOMAIN+path(lang,kind,slug)}">' for lang in LOCALES]
    entries.append(f'<link rel="alternate" hreflang="x-default" href="{DOMAIN+path("en",kind,slug)}">')
    return '\n'.join(entries)
def sectionheader(kicker,title,sub=''):
    return f'<p class="eyebrow">{esc(kicker)}</p><h2 class="display heading-lg">{esc(title)}</h2>'+ (f'<p class="muted section-lead">{esc(sub)}</p>' if sub else '')
def btn(text,url,style='primary'):
    return f'<a class="button button-{style}" href="{esc(url)}">{esc(text)} <span aria-hidden="true">↗</span></a>'
def artwork(kind):
    # Calm geometric abstract sketches, not misleading patient result imagery.
    paths={'rhinoplasty':'M85 24c-17 23-22 45-14 55 10 8 19 12 10 17-14 6-22 10-25 16','revision-rhinoplasty':'M86 28c-21 25-20 47-9 56 8 8 13 11 7 16M64 122q32 16 63-4','breast-augmentation':'M32 73c23-27 51-27 68 3 22-28 51-29 69-3','breast-reduction':'M27 75c33-18 52-20 73 11 23-31 47-28 73-11','abdominoplasty':'M49 18q-12 61 6 104m92-104q12 61-6 104M55 98q43 12 86 0','blepharoplasty':'M22 82q73-76 156 0M23 82q76 42 155 0','gynecomastia':'M40 25q-18 32-9 67m129-67q18 32 9 67M55 64q23-14 45 8 26-21 45-8','liposuction':'M36 18q18 44 0 76m128-76q-18 44 0 76M47 112q53 20 106 0'}
    return f'<svg aria-hidden="true" class="art-svg" viewBox="0 0 200 160" fill="none"><path d="{paths.get(kind,"")}" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/><circle cx="100" cy="80" r="63" stroke="currentColor" opacity=".16"/><circle cx="100" cy="80" r="47" stroke="currentColor" opacity=".09"/></svg>'

