def page(lang,kind,title,description,body,slug=None,schema=None):
    t=T[lang]; canonical=DOMAIN+path(lang,kind,slug)
    structured=json.dumps(schema or {},ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    html_page=f'''<!doctype html><html lang="{lang}" dir="{'rtl' if lang in RTL else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#f7f5f0"><title>{esc(title)}</title><meta name="description" content="{esc(description)}"><link rel="canonical" href="{canonical}">{hrelang(kind,slug)}
<meta property="og:type" content="website"><meta property="og:site_name" content="Hakkı İzmirli"><meta property="og:title" content="{esc(title)}"><meta property="og:description" content="{esc(description)}"><meta property="og:url" content="{canonical}"><meta property="og:locale" content="{lang}">
<meta name="twitter:card" content="summary"><link rel="icon" type="image/svg+xml" href="/assets/favicon.svg"><link rel="stylesheet" href="/assets/style.css"><script defer src="/assets/site.js"></script><script type="application/ld+json">{structured}</script></head>
<body data-locale="{lang}"><a class="skip-link" href="#main">{esc(t['skip'])}</a>{navigation(lang,'procedures' if kind=='proc' else kind,kind,slug)}<main id="main">{body}</main>{footer(lang)}<div class="mobile-quick-actions"><a href="tel:{PHONE}">{esc(t['call'])}</a><a href="{WHATSAPP}" rel="noopener noreferrer" target="_blank">WhatsApp</a><a href="{path(lang,'contact')}">{esc(t['nav'][5])}</a></div></body></html>'''
    dest=OUT/path(lang,kind,slug).lstrip('/')/'index.html'
    dest.parent.mkdir(parents=True,exist_ok=True)
    dest.write_text(html_page,encoding='utf-8')
    return canonical

